//! 🔺️ Explicit point/corner/page frontiers for original tessellated source rows.
use super::*;
impl GeometryPreparationCursor{
 pub(super) fn run_tessellation<G:GeometryGraph>(&mut self,read:&CapturedGeometryRead<'_,G>,mut current:Frame,entity:GeometryEntity<'_,G::Value>)->Result<(),&'static str>{let returned=self.read_frame(self.request.limits.depth);let mut result=Frame::new(0,0);if current.kind==12{if entity.name!="IFCCARTESIANPOINTLIST3D"{return Err("preparation-invalid-point-list")}let list=entity.args.first().and_then(GeometryValue::as_aggregate).filter(|v|!v.is_empty()&&v.len()<=u32::MAX as usize).ok_or("preparation-invalid-point-list")?;result.ordinal=current.ordinal;result.a=list.len()as u64;self.finish(result);return Ok(())}if read.graph.standard()!=GeometryStandard::Ifc4||entity.name!="IFCTRIANGULATEDFACESET"{return Err("preparation-unsupported-tessellation")}match current.stage{
 0=>{if entity.args.len()!=5{return Err("preparation-tessellation-arity")}let faces=entity.args[3].as_aggregate().filter(|v|!v.is_empty()&&v.len()<=u32::MAX as usize).ok_or("preparation-invalid-face-list")?;current.dims[1]=faces.len()as f64;self.call(current,Frame::new(12,Self::reference(entity,0,false)?),1)?},
 1=>{self.vertex_generation=self.vertex_generation.checked_add(1).ok_or("preparation-generation-limit")?;current.a=returned.ordinal-1;current.dims[0]=returned.a as f64;current.b=0;current.c=0;current.stage=2;self.write_frame(self.depth-1,current)},
 3=>{if current.b==current.dims[1]as u64{result.kind=3;self.finish(result)}else{let faces=entity.args[3].as_aggregate().ok_or("preparation-invalid-face-list")?;faces.get(current.b as usize).and_then(GeometryValue::as_aggregate).filter(|v|v.len()==3).ok_or("preparation-invalid-triangle")?;current.c=0;current.stage=4;self.write_frame(self.depth-1,current)}},
 4=>{if current.c==3{current.stage=7;self.write_frame(self.depth-1,current)}else{let face=entity.args[3].as_aggregate().and_then(|v|v.get(current.b as usize)).and_then(GeometryValue::as_aggregate).ok_or("preparation-invalid-triangle")?;let mut index=face.get(current.c as usize).and_then(GeometryValue::as_integer).filter(|v|*v>0&&*v<=u32::MAX as i64).ok_or("preparation-invalid-point-index")?;if let Some(pn)=entity.args.get(4){if !pn.is_unset(){let mapping=pn.as_aggregate().ok_or("preparation-invalid-pn-index")?;index=mapping.get(index as usize-1).and_then(GeometryValue::as_integer).filter(|v|*v>0&&*v<=u32::MAX as i64).ok_or("preparation-invalid-pn-index")?;}}let source=index as u32-1;if source as f64>=current.dims[0]{return Err("preparation-point-index-out-of-bounds")}let cached=self.vertices.as_ref().unwrap().get(source,self.vertex_generation)?;if cached!=0{current.base[0][current.c as usize]=(cached-1)as f64;current.c+=1;}else{let points=read.graph.entity(current.a as usize).ok_or("preparation-missing-point-list")?;let point=points.args.first().and_then(GeometryValue::as_aggregate).and_then(|v|v.get(source as usize)).and_then(GeometryValue::as_aggregate).filter(|v|v.len()==3).ok_or("preparation-coordinate-dimension")?;if points.constituent_count!=1{return Err("preparation-coordinate-dimension")}current.vector=Mat4(current.matrix).transform_point([Self::number(point.first())?,Self::number(point.get(1))?,Self::number(point.get(2))?]);if current.vector.iter().any(|v|!v.is_finite()){return Err("preparation-nonfinite-result")}current.dims[2]=source as f64;current.stage=5;}self.write_frame(self.depth-1,current)}},
 7=>{let ids=current.base[0];if ids[0]==ids[1]||ids[1]==ids[2]||ids[2]==ids[0]{return Err("preparation-degenerate-triangle")}let point=|index:f64|->Result<[f64;3],&'static str>{let points=self.points.as_ref().unwrap();let index=self.vertex_start+index as usize;Ok([points.get(index,0)?,points.get(index,1)?,points.get(index,2)?])};let a=point(ids[0])?;let b=subtract(point(ids[1])?,a);let c=subtract(point(ids[2])?,a);let extent=b.iter().chain(c.iter()).fold(0f64,|s,v|s.max(v.abs()));if !extent.is_finite()||extent==0.||cross(scale(b,1./extent),scale(c,1./extent)).iter().all(|v|*v==0.){return Err("preparation-degenerate-triangle")}current.vector=if determinant(&Mat4(current.matrix))<0.{[ids[0],ids[2],ids[1]]}else{ids};current.stage=8;self.write_frame(self.depth-1,current)},_=>return Err("preparation-invalid-tessellation-stage")};Ok(())}
 pub(super) fn tessellation_transfer(&mut self,turn:&mut PreparationTurn<'_,'_>)->Result<bool,&'static str>{let at=self.depth-1;let top=&self.frames.as_ref().unwrap()[at/FRAME_PAGE_SLOTS][at%FRAME_PAGE_SLOTS];if top.kind!=11||!matches!(top.stage,2|5|6|8){return Ok(false)}let stage=top.stage;if self.work>=self.request.limits.work{return Err("preparation-work-limit")}if stage==2{if self.points.is_none(){if self.admit(turn,std::mem::size_of::<mesh::RetainedMeshPages<f64>>(),0,0,1)?{self.points=Some(mesh::RetainedMeshPages::new(self.request.limits.vertices,self.request.limits.result_bytes)?)}return Ok(true)}if self.triangles.is_none(){if self.admit(turn,std::mem::size_of::<mesh::RetainedMeshPages<u32>>(),0,0,1)?{self.triangles=Some(mesh::RetainedMeshPages::new(self.request.limits.triangles,self.request.limits.result_bytes)?)}return Ok(true)}if self.vertices.is_none(){if self.admit(turn,std::mem::size_of::<vertex::SourceVertexIndex>(),0,0,1)?{self.vertices=Some(vertex::SourceVertexIndex::new(self.request.identity,self.request.limits.scratch_bytes));}return Ok(true)}if self.admit(turn,std::mem::size_of::<Frame>()*2,0,0,1)?{self.frames.as_mut().unwrap()[at/FRAME_PAGE_SLOTS][at%FRAME_PAGE_SLOTS].stage=3;}return Ok(true)}let mut current=self.read_frame(at);let overhead=std::mem::size_of::<Frame>()*2;if stage==6{let index=self.vertices.as_mut().unwrap();let before_work=index.work();let before_bytes=index.allocated_bytes();let result=index.put(current.dims[2]as u32,current.base[0][current.c as usize]as u32+1,self.vertex_generation,turn,overhead,self.request.limits.scratch_bytes-self.scratch_bytes);self.work+=index.work()-before_work;self.scratch_bytes+=index.allocated_bytes()-before_bytes;if result?{current.c+=1;current.stage=4;self.write_frame(at,current)}return Ok(true)}let result=if stage==5{let pages=self.points.as_mut().unwrap();let before_work=pages.work();let before_bytes=pages.allocated_bytes();let result=pages.append_funded(current.vector,turn,overhead,self.request.limits.result_bytes-self.result_bytes);self.work+=pages.work()-before_work;self.result_bytes+=pages.allocated_bytes()-before_bytes;if result?{current.base[0][current.c as usize]=(pages.len()-self.vertex_start-1)as f64;current.stage=6;true}else{false}}else{let pages=self.triangles.as_mut().unwrap();let before_work=pages.work();let before_bytes=pages.allocated_bytes();let result=pages.append_funded(current.vector.map(|v|v as u32),turn,overhead,self.request.limits.result_bytes-self.result_bytes);self.work+=pages.work()-before_work;self.result_bytes+=pages.allocated_bytes()-before_bytes;if result?{current.b+=1;current.stage=3;true}else{false}};if result{self.write_frame(at,current)}Ok(true)}
}
